/**
 * 아르케 그레이딩 테마 데이터.
 *
 * 아르케는 **머리 위가 광원이라 위가 밝고 아래가 어둡다** — 카르곤과 정확히 반대다. 아래 값
 * 전부가 그 한 문장의 결과다: 비네트 코어를 위로 올려 지면 쪽을 더 누르고, 스플릿 톤의 방향을
 * `-1`(하이라이트가 차갑고 암부가 따뜻함)로 선언한다. 저각 태양 아래의 석재는 하늘빛을 받은
 * 면이 서늘하고 그늘진 면이 지면에서 되튄 흙빛을 받는다.
 *
 * ⚠️ `warmthDirection` 이 `-1` 이라 **부호를 코드에 박은 검사가 전부 뒤집힌다.** 카르곤 값을
 * 복사해 색만 바꾸면 "스플릿이 없다"로 오판되고, 그것이 이 필드가 테마 데이터인 이유다.
 *
 * 여기 남길 주석은 **아르케 실측 근거**뿐이다. 메커니즘 근거는 계약·레이어에 남긴다.
 */

import type { GradeTheme } from '../../contracts/grade.js';

export const ARKE_GRADE: GradeTheme = {
  themeId: 'arke',
  alpha: {
    // 현대 AAA 비네트의 통상 대역(20~40%) 안쪽.
    vignette: 0.28,
    /*
     * 지면에서 되튄 흙빛. 시차 레이어의 `dust-shaft` 도 밝히는 방향(+)이라, 국소 근거가 있는
     * 최소량만 남기고 전역 색온도는 아래 gain/lift 가 맡는다.
     */
    warm: 0.045,
    /* 가장자리 **형상** 담당. 줄인 만큼이 정확히 gain 이 새로 먹는 감쇠 예산이 된다. */
    cool: 0.06,
    /*
     * 상한에 붙어 있다. tint 가 매우 밝은(휘도 0.906) 색이라 알파를 키워도 총 감쇠가 9.4% 의
     * 0.3 배, 즉 2.8% 에 그치기 때문이다.
     */
    gain: 0.3,
    /*
     * 0.05 는 **오버플로 여유가 정한 값**이다. R 채널 여유가 `gain × (1 − gainR) = 0.0812`
     * 뿐이고 lift 틴트의 R 이 1.0 이라 이 곱이 그 여유를 넘으면 흰 화소가 클리핑돼 warmth
     * 단조성이 잘려 나간다.
     */
    shadow: 0.05,
    // 밴딩을 깨는 최소량. 이 이상은 화면이 지저분해진다.
    grain: 0.03,
  },
  /**
   * 코어를 살짝 **위로** 올려 아래쪽 지면을 더 누른다(카르곤은 반대로 내렸다 — 그쪽 광원이
   * 발밑이라서). `outer` 는 최원거리 모서리(약 1.50)가 거의 최대에 닿는 값.
   */
  vignette: { centerY: -0.12, inner: 0.65, outer: 1.55 },
  /** 화면 **하단 1/4** 밖으로는 한 픽셀도 밝히지 않는다(시차 레인과의 중복 해소). */
  warm: { startY: 0.42, sideFalloff: 0.45 },
  cool: { topStart: -0.2, topEnd: -1, sideStart: 0.65, sideEnd: 1.05 },
  tint: {
    /** 지면 반사광 계열 흙빛. */
    warm: 0xc79a6e,
    /** 하늘 그림자. 무채에서 살짝 차가운 쪽으로만 밀어 색을 강요하지 않는다. */
    cool: 0x62707f,
    /** 무채에 가깝게 두어 색을 밀지 않는다. */
    grain: 0xb4b4b0,
    /**
     * 하이라이트 **한색**(카르곤은 황백이었다). B=255 라 흰 화소의 B 손실이 0 이고, R 을 낮춘
     * 만큼이 하이라이트 롤오프이자 warmth 기울기(−0.0812)의 원천이다. G 를 1.0 까지 올리지
     * 않은 이유는 lift 틴트의 G 가 들어갈 여유(0.0153)를 남겨야 하기 때문이다 — G=255 로 두면
     * 여유가 정확히 0 이 되어 암부 색조가 조금이라도 초록을 갖는 순간 오버플로한다.
     */
    gain: 0xbaf2ff,
    /**
     * 암부 **난색**. R 지배를 고른 이유는 카르곤이 청색을 고른 것과 같다 — **채도 대비 휘도가
     * 싸기** 때문이다(R 가중 0.2126). 암부 R−B 가 최대로 벌어지는 동안 절대 휘도 상승은
     * 0.0154 로 예산(0.06)의 1/4 에 그친다.
     */
    shadow: 0xff2200,
  },
  /** 하늘이 광원이므로 하이라이트가 차갑고 암부가 따뜻하다. */
  warmthDirection: -1,
};
